Is this code safe knowing that:

Header_mark_as_shared is always only called before an object crosses to other threads, no matter in which thread it resides in
The first call to Header_mark_as_shared will always happen in a single threaded context
Following calls to Header_mark_as_shared will always read is_shared as 1

I’m using the __atomic intrinsics from GCC and Clang.
#include <stdint.h>

typedef struct Header {
    uint8_t is_shared;
    uint64_t reference_count;
} Header;

void
Header_mark_as_shared(
    Header * const self
) {
    if (!self->is_shared) {
        ++self->reference_count;
        self->is_shared = 1;
    } else {
        __atomic_fetch_add(&self->reference_count, 1, __ATOMIC_RELAXED);
    }
}

void
Header_acquire(
    Header * const self
) {
    if (!self->is_shared) {
        ++self->reference_count;
    } else {
        __atomic_fetch_add(&self->reference_count, 1, __ATOMIC_RELAXED);
    }
}

uint8_t
Header_release(
    Header * const self
) {
    if (!self->is_shared) {
        return !--self->reference_count;
    } else {
        return __atomic_fetch_sub(&self->reference_count, 1, __ATOMIC_ACQ_REL) == 1;
    }
}

uint8_t
Header_is_one(
    Header const * const self
) {
    if (!self->is_shared) {
