import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int n = scanner.nextInt();
    int r = scanner.nextInt();
    int c = scanner.nextInt();

    int a, b, s;
    List < int[] > L = new ArrayList < > ();

    for (int i = 0; i < n; ++i) {
      a = scanner.nextInt() - 1;
      b = scanner.nextInt() - 1;
      s = scanner.nextInt();
      L.add(new int[] {
        Math.max(0, a - s), Math.min(r - 1, a + s)
      });
    }

